CREATE TABLE IF NOT EXISTS t (
    id integer,
    name text,
    CONSTRAINT t_pkey PRIMARY KEY (id)
);

CREATE AGGREGATE sum_v(v) (
    SFUNC = v_sfunc,
    STYPE = integer,
    INITCOND = '0'
);

CREATE AGGREGATE sum_with_v(integer) (
    SFUNC = acc_with_v,
    STYPE = bigint,
    INITCOND = '0'
);

CREATE OR REPLACE VIEW v_total AS
 SELECT sum_v(v.*) AS total
   FROM v;
